csstemplate:
.st-db{--st-ink:#203832;--st-muted:#53665f;--st-line:#d9e4de;--st-brand:#246858;--st-soft:#eff6f2;box-sizing:border-box;color:var(--st-ink);font-family:inherit;font-size:1rem;line-height:1.55;margin:1.25rem 0;max-width:100%}
.st-db *{box-sizing:border-box}.st-db h2,.st-db h3{color:var(--st-ink);line-height:1.25}.st-db h2{font-size:1.85rem;font-weight:700;margin:0 0 .7rem}.st-db h3{font-size:1.15rem;font-weight:700;margin:0 0 .65rem}
.st-hero{background:#eaf3ee;border:1px solid #c8dcd1;border-left:5px solid var(--st-brand);border-radius:12px;padding:1.6rem 1.8rem;margin-bottom:1.4rem}.st-hero p{margin:0 0 .85rem}.st-eyebrow{font-size:.72rem;font-weight:750;letter-spacing:.13em;text-transform:uppercase;color:#356454;margin:0 0 .7rem!important}.st-context{display:flex;gap:.5rem 1.8rem;flex-wrap:wrap;font-size:.83rem;color:#425e51}.st-db a{color:#1a6153;text-decoration:underline;text-underline-offset:3px}.st-db a:hover{color:#123e33}
.st-toolbar{display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;margin:1.4rem 0}.st-toolbar p{margin:0}.st-stamp{flex:none;border:1px solid var(--st-line);border-radius:6px;padding:.4rem .65rem;color:var(--st-muted);font-size:.75rem;white-space:nowrap}.st-muted,.st-hint,.st-small,.st-footnote,.st-meta{color:var(--st-muted)}.st-small{font-size:.78rem;line-height:1.5;margin-top:.3rem;overflow-wrap:anywhere}.st-hint{font-size:.82rem;line-height:1.5;margin:.2rem 0 .45rem}.st-footnote{font-size:.82rem;margin:1rem 0}.st-code{display:block;font-size:.75rem;font-weight:700;letter-spacing:.035em;color:var(--st-brand);margin-bottom:.22rem}.st-title{display:block;font-weight:650;font-size:.96rem;text-decoration:none!important;line-height:1.4}
.st-table-wrap{overflow-x:auto;border:1px solid var(--st-line);border-radius:10px}.st-table{width:100%;min-width:880px;border-collapse:collapse;margin:0;background:#fff}.st-table th{text-transform:uppercase;font-weight:700;font-size:.68rem;letter-spacing:.06em;color:#415b4e;background:#f2f6f3;padding:.85rem 1rem;white-space:nowrap;text-align:left}.st-table td{padding:1rem;border-top:1px solid #e1e9e4;vertical-align:top;font-size:.88rem}.st-table td:first-child{width:35%;min-width:270px}.st-table td:nth-child(2){width:15%}.st-table td:nth-child(3){width:13%}.st-table td:nth-child(4){width:13%}.st-table tbody tr:hover{background:#f8fbf9}.st-actions{width:50px}.st-actions .dropdown{display:inline-block}
.st-pill{display:inline-block;max-width:100%;font-size:.78rem;line-height:1.4;font-weight:700;padding:.34rem .66rem;border-radius:6px;border:1px solid #cfd9d3;background:#f1f4f2;color:#4c5b53;white-space:nowrap}.st-pill[data-state="Bestanden"]{background:#e8f4ed;color:#175b38;border-color:#adcfba}.st-pill[data-state="Fehler"]{background:#fbecec;color:#9a3030;border-color:#e7baba}.st-pill[data-state="Blockiert"]{background:#fff4df;color:#785217;border-color:#e3cd9d}.st-pill[data-state="Entfällt"]{background:#edf0f5;color:#515c70;border-color:#cdd4e0}.st-statusline,.st-topline{display:flex;gap:1rem;align-items:center;justify-content:flex-start;flex-wrap:wrap}.st-topline{justify-content:space-between}.st-statusline{font-size:.9rem}
.st-panel{background:#fff;border:1px solid var(--st-line);border-radius:10px;padding:1.4rem;margin:1.2rem 0;min-width:0}.st-panel legend{float:none;width:auto;padding:0 .45rem;margin:0;font-size:1.12rem;font-weight:700;color:var(--st-ink)}.st-step{font-size:.74rem;color:var(--st-brand);border-right:1px solid #bdcfc2;margin-right:.65rem;padding-right:.65rem}.st-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:1.2rem 1.4rem}.st-wide{grid-column:1/-1}.st-field{min-width:0}.st-label{font-size:.87rem;font-weight:700;margin-bottom:.35rem}.st-required{color:#9b3434}.st-input input[type=text],.st-input input[type=url],.st-input select,.st-input textarea{max-width:100%;width:100%}.st-input .mod-data-input{max-width:100%}.st-input .inline-req{display:none}.st-input label{margin-bottom:0}.st-input .form-select{white-space:normal}.st-input textarea{min-height:100px}.st-note{border:1px solid #d2e0d6;background:#f6f9f6;border-radius:8px;padding:1rem 1.25rem;color:#385744;font-size:.87rem}
.st-details{border:1px solid var(--st-line);border-radius:10px;margin:1.2rem 0;background:#fff}.st-details summary{padding:1rem 1.4rem;font-weight:700;cursor:pointer;background:#f4f7f4;border-radius:10px}.st-details[open] summary{border-bottom:1px solid var(--st-line);border-radius:10px 10px 0 0}.st-details-body{padding:1.4rem}.st-detail{min-width:0}.st-detail dt{font-size:.77rem;font-weight:700;color:var(--st-muted);margin-bottom:.28rem}.st-detail dd{margin:0;overflow-wrap:anywhere}.st-detail dd:empty::after,.st-result-text:empty::after{content:"Noch keine Angabe";color:#65756c;font-style:italic}.st-detail img{max-width:100%;height:auto}.st-panel dl{margin:0}.st-prose ol{padding-left:1.4rem}.st-prose li{margin:.45rem 0}.st-prose p:last-child{margin-bottom:0}.st-meta{font-size:.76rem;border-top:1px solid var(--st-line);padding-top:1rem;margin:1.5rem 0}.st-comments{margin:1rem 0}.st-search-heading{margin:0 0 1.2rem}.st-db :focus-visible{outline:3px solid #386a98;outline-offset:3px}
@media(max-width:700px){.st-grid{grid-template-columns:minmax(0,1fr)}.st-wide{grid-column:auto}.st-hero{padding:1.2rem}.st-db h2{font-size:1.45rem}.st-toolbar{display:block}.st-stamp{display:inline-block;margin-top:.7rem}.st-panel,.st-details-body{padding:1rem}.st-context{display:block}.st-context span{display:block;margin-top:.3rem}}
@media print{.st-actions,.st-comments{display:none}.st-hero,.st-panel{break-inside:avoid}.st-db{font-size:10pt}.st-table{min-width:0}.st-table th,.st-table td{padding:.4rem}.st-table-wrap{overflow:visible}.st-db a{color:#203832}}
